[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Air Jordan Sneaker Resale Market Analysis (2023–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #0d1117;
    --surface: #161b22;
    --surface2: #1c2128;
    --border: #30363d;
    --text: #e6edf3;
    --muted: #8b949e;
    --accent: #f97316;
    --accent2: #3b82f6;
    --accent3: #10b981;
    --accent4: #a855f7;
    --neg: #ef4444;
    --pos: #22c55e;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: var(--bg);
    color: var(--text);
    font-family: 'Inter', system-ui, -apple-system, sans-serif;
    font-size: 14px;
    line-height: 1.6;
  }
  a { color: var(--accent2); }

  /* ── Layout ── */
  .page-header {
    background: linear-gradient(135deg, #1a1f2e 0%, #0d1117 60%);
    border-bottom: 1px solid var(--border);
    padding: 40px 48px 32px;
  }
  .page-header .eyebrow {
    font-size: 11px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--accent);
    font-weight: 600;
    margin-bottom: 10px;
  }
  .page-header h1 {
    font-size: 28px;
    font-weight: 700;
    letter-spacing: -0.5px;
    margin-bottom: 8px;
  }
  .page-header .subtitle {
    color: var(--muted);
    font-size: 14px;
    max-width: 680px;
  }
  .page-header .meta {
    margin-top: 16px;
    display: flex;
    gap: 24px;
    font-size: 12px;
    color: var(--muted);
  }
  .page-header .meta span { display: flex; align-items: center; gap: 5px; }

  main { max-width: 1280px; margin: 0 auto; padding: 40px 48px 80px; }

  section { margin-bottom: 56px; }
  .section-header {
    display: flex;
    align-items: baseline;
    gap: 12px;
    margin-bottom: 24px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--border);
  }
  .section-header .section-num {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.1em;
    color: var(--accent);
    text-transform: uppercase;
  }
  .section-header h2 {
    font-size: 20px;
    font-weight: 700;
    letter-spacing: -0.3px;
  }

  /* ── KPI Cards ── */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 32px;
  }
  .kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 18px;
    position: relative;
    overflow: hidden;
  }
  .kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: var(--accent-color, var(--accent));
  }
  .kpi-card .kpi-label {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--muted);
    margin-bottom: 8px;
  }
  .kpi-card .kpi-value {
    font-size: 30px;
    font-weight: 800;
    letter-spacing: -1px;
    line-height: 1;
    color: var(--accent-color, var(--text));
  }
  .kpi-card .kpi-sub {
    font-size: 12px;
    color: var(--muted);
    margin-top: 6px;
  }

  /* ── Charts ── */
  .chart-grid-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
  }
  .chart-grid-3 {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
  }
  .chart-box {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px;
  }
  .chart-box.full { grid-column: 1 / -1; }
  .chart-box h3 {
    font-size: 13px;
    font-weight: 700;
    color: var(--text);
    margin-bottom: 4px;
  }
  .chart-box .chart-desc {
    font-size: 11px;
    color: var(--muted);
    margin-bottom: 16px;
  }
  .chart-box canvas { max-height: 280px; }
  .chart-box canvas.tall { max-height: 340px; }
  .chart-box canvas.short { max-height: 200px; }

  /* ── Tables ── */
  .table-wrap {
    overflow-x: auto;
    margin-bottom: 20px;
  }
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
  }
  thead th {
    background: var(--surface2);
    color: var(--muted);
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    padding: 10px 14px;
    text-align: left;
    border-bottom: 1px solid var(--border);
    white-space: nowrap;
  }
  thead th.right { text-align: right; }
  tbody tr {
    border-bottom: 1px solid var(--border);
    transition: background 0.15s;
  }
  tbody tr:hover { background: var(--surface2); }
  tbody td {
    padding: 10px 14px;
    color: var(--text);
    white-space: nowrap;
  }
  tbody td.right { text-align: right; font-variant-numeric: tabular-nums; }
  tbody td.pos { color: var(--pos); font-weight: 600; }
  tbody td.neg { color: var(--neg); font-weight: 600; }
  .rank-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 22px; height: 22px;
    border-radius: 50%;
    font-size: 11px;
    font-weight: 700;
    background: var(--surface2);
    color: var(--muted);
    margin-right: 6px;
  }
  .rank-badge.gold { background: #854d0e; color: #fbbf24; }
  .rank-badge.silver { background: #374151; color: #d1d5db; }
  .rank-badge.bronze { background: #44261a; color: #fb923c; }

  /* ── Condition badges ── */
  .badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 12px;
    font-size: 11px;
    font-weight: 600;
  }
  .badge-ds { background: #14532d; color: #86efac; }
  .badge-vnds { background: #1e3a5f; color: #93c5fd; }
  .badge-used { background: #450a0a; color: #fca5a5; }

  /* ── Insight callouts ── */
  .insight-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-top: 20px;
  }
  .insight-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-left: 3px solid var(--accent-color, var(--accent));
    border-radius: 8px;
    padding: 14px 16px;
  }
  .insight-card .ic-label {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent-color, var(--accent));
    margin-bottom: 4px;
  }
  .insight-card .ic-text {
    font-size: 13px;
    color: var(--muted);
    line-height: 1.5;
  }
  .insight-card .ic-text strong { color: var(--text); }

  /* ── Progress bars ── */
  .bar-row { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
  .bar-label { width: 160px; font-size: 12px; color: var(--muted); flex-shrink: 0; text-overflow: ellipsis; overflow: hidden; white-space: nowrap; }
  .bar-track { flex: 1; height: 8px; background: var(--surface2); border-radius: 4px; overflow: hidden; }
  .bar-fill { height: 100%; border-radius: 4px; transition: width 0.6s ease; }
  .bar-val { width: 70px; font-size: 12px; color: var(--text); text-align: right; font-variant-numeric: tabular-nums; }

  /* ── Velocity visualization ── */
  .velocity-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 12px;
  }
  .velocity-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px;
  }
  .velocity-card .vc-name {
    font-size: 12px;
    font-weight: 700;
    color: var(--text);
    margin-bottom: 12px;
  }
  .velocity-segment {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 6px;
  }
  .velocity-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
  .velocity-label { font-size: 11px; color: var(--muted); flex: 1; }
  .velocity-pct { font-size: 12px; font-weight: 600; color: var(--text); }

  /* ── Recommendations ── */
  .rec-grid {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 16px;
  }
  .rec-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px;
  }
  .rec-card .rec-icon {
    font-size: 22px;
    margin-bottom: 10px;
  }
  .rec-card .rec-title {
    font-size: 14px;
    font-weight: 700;
    color: var(--text);
    margin-bottom: 8px;
  }
  .rec-card .rec-body {
    font-size: 13px;
    color: var(--muted);
    line-height: 1.6;
  }
  .rec-card .rec-body strong { color: var(--text); }

  /* ── Crosstab ── */
  .crosstab td { min-width: 100px; }

  /* ── Footer ── */
  footer {
    border-top: 1px solid var(--border);
    padding: 24px 48px;
    color: var(--muted);
    font-size: 12px;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  @media (max-width: 1100px) {
    .kpi-grid { grid-template-columns: repeat(3, 1fr); }
    .chart-grid-2, .chart-grid-3 { grid-template-columns: 1fr; }
    .velocity-grid { grid-template-columns: 1fr 1fr; }
    .rec-grid { grid-template-columns: 1fr 1fr; }
    .insight-row { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>

<!-- ════════════════════ PAGE HEADER ════════════════════ -->
<header class="page-header">
  <div class="eyebrow">Market Intelligence Report</div>
  <h1>Air Jordan Sneaker Resale Market Analysis</h1>
  <p class="subtitle">A comprehensive analysis of 5,000 secondary-market transactions examining pricing dynamics, profit margins, inventory velocity, and channel performance across models, colorways, and conditions — 2023 through 2026.</p>
  <div class="meta">
    <span>📅 Transactions: Jan 1, 2023 – Sep 27, 2025</span>
    <span>📦 Dataset: 5,000 records</span>
    <span>🏷️ Models: 5 Air Jordan silhouettes</span>
    <span>🛍️ Channels: 5 sales platforms</span>
    <span>📊 Source: jordan_market_dataset_2026.csv</span>
  </div>
</header>

<main>

<!-- ════════════════════ SECTION 0: KPI DASHBOARD ════════════════════ -->
<section id="kpi-dashboard">
  <div class="section-header">
    <span class="section-num">Dashboard</span>
    <h2>Key Performance Indicators</h2>
  </div>

  <div class="kpi-grid">
    <div class="kpi-card" style="--accent-color: #f97316;">
      <div class="kpi-label">Avg Profit Margin</div>
      <div class="kpi-value">$82.06</div>
      <div class="kpi-sub">Per transaction · Range: −$114 to +$575</div>
    </div>
    <div class="kpi-card" style="--accent-color: #22c55e;">
      <div class="kpi-label">Resale Premium Rate</div>
      <div class="kpi-value">61.3%</div>
      <div class="kpi-sub">Transactions above retail (3,066 of 5,000)</div>
    </div>
    <div class="kpi-card" style="--accent-color: #3b82f6;">
      <div class="kpi-label">Avg Days in Inventory</div>
      <div class="kpi-value">22.5</div>
      <div class="kpi-sub">Days per sale · GOAT/StockX: ~7.5 days</div>
    </div>
    <div class="kpi-card" style="--accent-color: #a855f7;">
      <div class="kpi-label">Resale-to-Retail Ratio</div>
      <div class="kpi-value">1.43×</div>
      <div class="kpi-sub">Avg $273.23 resale vs. $191.17 retail</div>
    </div>
    <div class="kpi-card" style="--accent-color: #f59e0b;">
      <div class="kpi-label">Top Colorway Margin</div>
      <div class="kpi-value">$89.23</div>
      <div class="kpi-sub">Pine Green · 566 transactions</div>
    </div>
  </div>

  <div class="chart-grid-2">
    <div class="chart-box">
      <h3>Profit Margin Distribution</h3>
      <p class="chart-desc">All 5,000 transactions bucketed by profit margin (USD). Wide spread (σ = $159) reflects condition stratification.</p>
      <canvas id="chartMarginDist" class="short"></canvas>
    </div>
    <div class="chart-box">
      <h3>Key Ratio Benchmarks</h3>
      <p class="chart-desc">Summary of core pricing statistics across the full dataset.</p>
      <canvas id="chartKeyRatios" class="short"></canvas>
    </div>
  </div>
</section>

<!-- ════════════════════ SECTION 1: MARKET OVERVIEW ════════════════════ -->
<section id="market-overview">
  <div class="section-header">
    <span class="section-num">01</span>
    <h2>Market Overview &amp; Transaction Summary</h2>
  </div>

  <div class="chart-grid-3">
    <div class="chart-box" style="grid-column: span 2;">
      <h3>Annual Transaction Volume &amp; Average Resale Price</h3>
      <p class="chart-desc">2025 is a partial year (through Sep 27). Volume and pricing remain stable across years.</p>
      <canvas id="chartYearlyOverview"></canvas>
    </div>
    <div class="chart-box">
      <h3>Below vs. Above Retail</h3>
      <p class="chart-desc">38.68% of all transactions clear at a loss vs. retail — predominantly Used-condition sales.</p>
      <canvas id="chartAboveBelow" class="short"></canvas>
    </div>
  </div>

  <div class="table-wrap">
    <table>
      <thead>
        <tr>
          <th>Year</th>
          <th class="right">Transactions</th>
          <th class="right">Avg Retail (USD)</th>
          <th class="right">Avg Resale (USD)</th>
          <th class="right">Avg Profit Margin (USD)</th>
          <th class="right">Avg Days in Inventory</th>
        </tr>
      </thead>
      <tbody>
        <tr><td>2023</td><td class="right">1,816</td><td class="right">$191.17</td><td class="right">$272.50</td><td class="right pos">$80.84</td><td class="right">21.97</td></tr>
        <tr><td>2024</td><td class="right">1,913</td><td class="right">$191.17</td><td class="right">$274.06</td><td class="right pos">$81.61</td><td class="right">23.16</td></tr>
        <tr><td>2025 (YTD)</td><td class="right">1,271</td><td class="right">$191.17</td><td class="right">$273.03</td><td class="right pos">$84.47</td><td class="right">22.16</td></tr>
        <tr style="font-weight:700; background: var(--surface2);">
          <td>All Years</td><td class="right">5,000</td><td class="right">$191.17</td><td class="right">$273.23</td><td class="right pos">$82.06</td><td class="right">22.47</td>
        </tr>
      </tbody>
    </table>
  </div>

  <div class="insight-row">
    <div class="insight-card" style="--accent-color: #f97316;">
      <div class="ic-label">Market Stability</div>
      <div class="ic-text">Average resale prices have been remarkably stable across all three years — within a <strong>$1.56 band</strong> ($272.50–$274.06). This suggests a mature, equilibrium-seeking market with no dramatic macro-level pricing shocks.</div>
    </div>
    <div class="insight-card" style="--accent-color: #22c55e;">
      <div class="ic-label">Margin Trajectory</div>
      <div class="ic-text">Average profit margins show a modest but consistent upward trend: <strong>$80.84 → $81.61 → $84.47</strong>. The 2025 YTD acceleration (+$2.86 over 2024) may signal improving market conditions or a shift toward higher-value condition mixes.</div>
    </div>
  </div>
</section>

<!-- ════════════════════ SECTION 2: MODEL & COLORWAY ════════════════════ -->
<section id="model-colorway-analysis">
  <div class="section-header">
    <span class="section-num">02</span>
    <h2>Performance by Shoe Model &amp; Colorway</h2>
  </div>

